measures.qlik_expression:
// Decayed GPA Quality Index, 0–100
// - Uses last 180 days anchored to max grade date
// - Falls back to all-time GPA if the 180d window is empty

25 *
(
  // -------- helpers computed via AGGR (legal in Qlik) --------
  // window row count
  If(
    Sum(
      Aggr(
        If(
          Floor(GRADED_DATE_DATE) >= Floor(Max({1} TOTAL GRADED_DATE_DATE)) - 179
          and Floor(GRADED_DATE_DATE) <= Floor(Max({1} TOTAL GRADED_DATE_DATE)),
          1, 0
        ),
        GRADE_ID
      )
    ) > 0,

    // ---------- WINDOWED, DECAYED GPA (when window has rows) ----------
    // numerator
    Sum(
      Aggr(
        If(
          Floor(GRADED_DATE_DATE) >= Floor(Max({1} TOTAL GRADED_DATE_DATE)) - 179
          and Floor(GRADED_DATE_DATE) <= Floor(Max({1} TOTAL GRADED_DATE_DATE)),
          // decay weight (half-life 30 days)
          Exp(
            -0.6931471805599453 *
            ( Floor(Max({1} TOTAL GRADED_DATE_DATE)) - Floor(GRADED_DATE_DATE) ) / 30
          )
          *
          // GPA mapping: numeric % OR letters
          If(
            IsNum(GRADE),
              RangeMax(0, RangeMin(4,
                If(GRADE>=90, 4,
                If(GRADE>=85, 3.7 + (GRADE-85)*0.06,
                If(GRADE>=75, 3.0 + (GRADE-75)*0.07,
                If(GRADE>=65, 2.0 + (GRADE-65)*0.10,
                If(GRADE>=50, 1.0 + (GRADE-50)*0.0667, 0))))))),
              Pick(
                Match(Upper(Trim(GRADE)),
                  'A+','A','A-','B+','B','B-','C+','C','C-','D+','D','D-','F',
                  'HD','DI','CR','P','N','PASS','FAIL'
                ),
                4.0,4.0,3.7,3.3,3.0,2.7,2.3,2.0,1.7,1.3,1.0,0.7,0.0,
                4.0,3.7,2.5,1.0,0.0,1.0,0.0
              )
          ),
          0
        ),
        GRADE_ID
      )
    )
    /
    // denominator (guarded)
    Max(
      1e-9,
      Sum(
        Aggr(
          If(
            Floor(GRADED_DATE_DATE) >= Floor(Max({1} TOTAL GRADED_DATE_DATE)) - 179
            and Floor(GRADED_DATE_DATE) <= Floor(Max({1} TOTAL GRADED_DATE_DATE)),
            Exp(
              -0.6931471805599453 *
              ( Floor(Max({1} TOTAL GRADED_DATE_DATE)) - Floor(GRADED_DATE_DATE) ) / 30
            ),
            0
          ),
          GRADE_ID
        )
      )
    ),

    // ---------- FALLBACK: ALL-TIME GPA (no window rows) ----------
    (
      Sum( Aggr(
        If(
          IsNum(GRADE),
            RangeMax(0, RangeMin(4,
              If(GRADE>=90, 4,
              If(GRADE>=85, 3.7 + (GRADE-85)*0.06,
              If(GRADE>=75, 3.0 + (GRADE-75)*0.07,
              If(GRADE>=65, 2.0 + (GRADE-65)*0.10,
              If(GRADE>=50, 1.0 + (GRADE-50)*0.0667, 0))))))),
            Pick(
              Match(Upper(Trim(GRADE)),
                'A+','A','A-','B+','B','B-','C+','C','C-','D+','D','D-','F',
                'HD','DI','CR','P','N','PASS','FAIL'
              ),
              4.0,4.0,3.7,3.3,3.0,2.7,2.3,2.0,1.7,1.3,1.0,0.7,0.0,
              4.0,3.7,2.5,1.0,0.0,1.0,0.0
            )
        ),
        GRADE_ID
      )) 
      /
      Max(1, Sum( Aggr(1, GRADE_ID) ))
    )
  )
)

